import{_ as a,o as n,c as e,a3 as t}from"./chunks/framework.Dz5Q8p4s.js";const g=JSON.parse('{"title":"Benchmarking Scientific Understanding and Reasoning for Video Generation using VideoScience-Bench","description":"","frontmatter":{"title":"Benchmarking Scientific Understanding and Reasoning for Video Generation using VideoScience-Bench","arxiv":"2512.02942","date":"2025-12-02","authors":"Lanxiang Hu, Abhilash Shankarampeta, Yixin Huang, Zilin Dai, Haoyang Yu, Yujie Zhao, Haoqiang Kang, Daniel Zhao, Tajana Rosing, Hao Zhang","categories":"cs.CV, cs.AI","topics":"物理感知视频生成, 科学推理评测, VLM-as-a-Judge","outline":[2,2]},"headers":[],"relativePath":"papers/2512.02942.md","filePath":"papers/2512.02942.md","lastUpdated":null}'),p={name:"papers/2512.02942.md"};function l(r,s,i,o,m,c){return n(),e("div",null,[...s[0]||(s[0]=[t('<h1 id="benchmarking-scientific-understanding-and-reasoning-for-video-generation-using-videoscience-bench" tabindex="-1">Benchmarking Scientific Understanding and Reasoning for Video Generation using VideoScience-Bench <a class="header-anchor" href="#benchmarking-scientific-understanding-and-reasoning-for-video-generation-using-videoscience-bench" aria-label="Permalink to &quot;Benchmarking Scientific Understanding and Reasoning for Video Generation using VideoScience-Bench&quot;">​</a></h1><table tabindex="0"><thead><tr><th>项</th><th>内容</th></tr></thead><tbody><tr><td><strong>arXiv</strong></td><td><a href="https://arxiv.org/abs/2512.02942" target="_blank" rel="noreferrer">2512.02942</a></td></tr><tr><td><strong>提交日期</strong></td><td>2025-12-02</td></tr><tr><td><strong>作者</strong></td><td>Lanxiang Hu, Abhilash Shankarampeta, Yixin Huang, Zilin Dai, Haoyang Yu, Yujie Zhao, Haoqiang Kang, Daniel Zhao, Tajana Rosing, Hao Zhang</td></tr><tr><td><strong>分类</strong></td><td>cs.CV, cs.AI</td></tr><tr><td><strong>一句话</strong></td><td>用 200 条每条至少复合两个本科级物理化学概念的 prompt，把视频模型当推理器而非生成器来考，并配一个&quot;清单 + 关键帧 + CV 证据表&quot;的 VLM 判分器把打分从幻觉式好评拉回专家标注。</td></tr></tbody></table><blockquote><p><strong>所属教程</strong>：<a href="/notes/tutorials/physics-aware">物理感知视频生成</a></p></blockquote><h2 id="§-1-—-研究问题与重要性" tabindex="-1">§ 1 — 研究问题与重要性 <a class="header-anchor" href="#§-1-—-研究问题与重要性" aria-label="Permalink to &quot;§ 1 — 研究问题与重要性&quot;">​</a></h2><p>现有视频生成评测的物理部分基本停留在常识层面：球会往下掉、镜子会反射、水会往低处流。这些题目用初中知识就能判对错，因而对&quot;模型是否理解世界&quot;这个问题的分辨率极低。论文提出的问题更锋利：视频模型能不能在<strong>多个科学概念交互</strong>的场景下推出正确结果。文中给的对照极具说服力——&quot;气球靠近烛焰&quot;是常识题，谁都知道会爆；&quot;装了少量水的气球靠近烛焰&quot;是推理题，需要同时调用水的高比热容和热传导才能预测出气球不会立刻破裂。同类还有&quot;贴在低频扬声器前的透明水管里的水流&quot;，需要振动、波与材料性质三者复合。这件事重要的原因是：世界模型的价值在于预测真实过程的结果，而真实过程从来不由单条定律决定。</p><h2 id="§-2-—-前人工作与不足" tabindex="-1">§ 2 — 前人工作与不足 <a class="header-anchor" href="#§-2-—-前人工作与不足" aria-label="Permalink to &quot;§ 2 — 前人工作与不足&quot;">​</a></h2><p>VBench 与 VBench++ 把生成质量拆成主体一致性、运动平滑度、时序闪烁等层次化维度；WorldModelBench、VideoPhy、VideoPhy-2、PhyGenBench、Physion、IntPhys 则各自从物理常识、动态连贯性、材质交互角度建立了评测。论文对它们的批评是精确的：这些 benchmark 的场景本身只需要基础或高中水平的科学知识，因此即使模型全部答对，也无法区分&quot;记住了大量下落视频&quot;与&quot;理解了重力&quot;。评测方法侧同样有缺口——PhyGenEval 采用三层级框架，每层强制二值判断，导致分数量化、相近模型之间失去分辨率，而且它的规则式提问（&quot;球是否向下落&quot;&quot;水流是否正确&quot;）无法覆盖轨迹一致性、加速度模式、动量守恒这类整体性判断；VideoScore2 的物理一致性维度是为宽泛的常识违规设计的，面对需要深层科学推理的题目相关性很低；T2V-CompBench 的 VLM 组件难以捕捉细微的物理违规。这些缺口不是设计疏忽，而是因为在&quot;复合概念&quot;这个题型出现之前，单一原则的二值判据是够用的。</p><h2 id="§-3-—-重建作者的思考路径" tabindex="-1">§ 3 — 重建作者的思考路径 <a class="header-anchor" href="#§-3-—-重建作者的思考路径" aria-label="Permalink to &quot;§ 3 — 重建作者的思考路径&quot;">​</a></h2><p>一个受过科学训练的人看世界，用的是一套原理组合，然后预期一个现象。既有的观察是：模型在单原则常识题上已经接近饱和，而人类科学推理的难度恰恰来自&quot;两个原理同时起作用&quot;。于是设计题目的原则自然浮现——每道题必须至少需要两个本科级概念。接下来的问题是判分。人工标注不可扩展，直接让 VLM 打分则会遇到一个既有的坏经验：非推理型 VLM（如 GPT-4o）倾向于给虚高的分数、产生大量假阳性，且给不出可核查的理由。这条失败模式指向一个补救方向：不要让判分器自由发挥，而是先把&quot;该看什么&quot;固化成清单，再逼它为每一次扣分指出具体帧和具体证据。至于哪些证据不该交给 VLM 生成，答案是那些确定性 CV 工具已经做得更好的部分——实体是否存在、身份是否跨帧保持、运动方向与幅度多少。</p><h2 id="§-4-—-核心-intuition" tabindex="-1">§ 4 — 核心 Intuition <a class="header-anchor" href="#§-4-—-核心-intuition" aria-label="Permalink to &quot;§ 4 — 核心 Intuition&quot;">​</a></h2><p>区分&quot;生成器&quot;和&quot;推理器&quot;的最小改动，是把 prompt 从描述一个现象改成描述一个<strong>实验装置</strong>，然后要求模型自己推出该装置会产生什么现象。同理，把 VLM 判分从&quot;打个分&quot;改成&quot;先按清单逐条核对、每一次扣分都必须指出帧号和证据&quot;，就把幻觉的空间挤掉了。</p><h2 id="§-5-—-具体方法与完整-pipeline" tabindex="-1">§ 5 — 具体方法与完整 Pipeline <a class="header-anchor" href="#§-5-—-具体方法与完整-pipeline" aria-label="Permalink to &quot;§ 5 — 具体方法与完整 Pipeline&quot;">​</a></h2><p>以&quot;铝碘反应&quot;这道题走一遍。题目文本是：往盛有铝粉与碘晶体混合物的浅盘中滴几滴水。标准答案（expected phenomenon）写明：加水之前无反应，加水之后混合物自发点燃，出现紫蓝色闪光与烟。</p><p><strong>建库</strong>分三步。八位对应学科的研究生各选若干类别、各写 20 条 prompt，每条必须要求至少两个科学概念的推理，题材取自公开的教学实验资料以保证科学正确性，且目标现象要能在 10 秒以内的视频里呈现。其中两人另外整理了 40 条 I2V 题目，每条配一段展示该实验的参考视频，并从开头截一帧作为条件图像。然后全体评审交叉核对每份 20 条的具体性、流程准确性与预期结果清晰度。最后用 Sora-2 与 Wan-2.5-T2V-Preview 生成每条 prompt 的开头几秒，确认关键实验组件与装置确实能被画出来。最终 T2V 分支 160 条、I2V 分支 40 条，覆盖 14 个主题（物理 9、化学 5）与 103 个概念（物理 79、化学 24）。</p><p><strong>判分</strong>用 VideoScience-Judge。先由一个 LLM agent 结合题目与标准答案生成该题专属的检查清单，条目必须是可视觉观察的陈述句而非问句。再抽关键帧，在有参考视频的 I2V 分支上用参考帧引导判分器定位清单条目被违反的时刻。同时跑一组确定性 CV 模块产出证据表：GroundingDINO 做开放词表检测核验实体与属性，ByteTrack 做身份关联并量化时空连贯性，RAFT 光流量化运动方向与幅度，CLIP4Clip 算文本—视频对齐，有参考视频时补一个 VGG backbone 的 LPIPS 相似度。每个模块输出紧凑的 JSON 记录（时刻、类型、区域、分数、属性）。最后把清单与证据表选择性地拼进 prompt，要求 VLM 把&quot;每类中被满足的条目比例&quot;转换成四点评分。</p><h2 id="§-6-—-核心数学推导" tabindex="-1">§ 6 — 核心数学推导 <a class="header-anchor" href="#§-6-—-核心数学推导" aria-label="Permalink to &quot;§ 6 — 核心数学推导&quot;">​</a></h2><p>本文的形式化只有一处：五个维度的加权聚合。每个维度按四点序数量表打分，1 为缺失或矛盾，2 为弱或部分错误，3 为大体正确，4 为明确正确。总分为</p><p class="katex-block"><span class="katex-display"><span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.0576em;">S</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:2.3521em;vertical-align:-1.3021em;"></span><span class="mop op-limits"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:1.05em;"><span style="top:-1.8479em;margin-left:0em;"><span class="pstrut" style="height:3.05em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight" style="margin-right:0.0315em;">k</span></span></span></span><span style="top:-3.05em;"><span class="pstrut" style="height:3.05em;"></span><span><span class="mop op-symbol large-op">∑</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:1.3021em;"><span></span></span></span></span></span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0269em;">w</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3361em;"><span style="top:-2.55em;margin-left:-0.0269em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight" style="margin-right:0.0315em;">k</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord"><span class="mord mathnormal">s</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3361em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight" style="margin-right:0.0315em;">k</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mpunct">,</span><span class="mspace" style="margin-right:2em;"></span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mop op-limits"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:1.05em;"><span style="top:-1.8479em;margin-left:0em;"><span class="pstrut" style="height:3.05em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight" style="margin-right:0.0315em;">k</span></span></span><span style="top:-3.05em;"><span class="pstrut" style="height:3.05em;"></span><span><span class="mop op-symbol large-op">∑</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:1.3021em;"><span></span></span></span></span></span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0269em;">w</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3361em;"><span style="top:-2.55em;margin-left:-0.0269em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight" style="margin-right:0.0315em;">k</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.8389em;vertical-align:-0.1944em;"></span><span class="mord">1</span><span class="mpunct">,</span></span></span></span></span></p><p>其中权重取 Phenomenon Congruency <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">0.3</span></span></span></span>、Prompt Consistency <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">0.2</span></span></span></span>、Spatio-temporal Coherence <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">0.2</span></span></span></span>、Correct Dynamism <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">0.15</span></span></span></span>、Immutability <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">0.15</span></span></span></span>。权重分配本身就是一个论点：现象是否正确出现被赋予最大权重，其次是实验装置是否搭对，而&quot;物体不该变时不变&quot;和&quot;其他物理定律是否遵守&quot;权重最低。这个排序隐含的判断是——在科学推理评测里，装置搭错就没什么可评的，而画面稳定性是必要但远非充分的条件。</p><p>跨模型的一致性用两个秩相关量化：Kendall 的 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.4306em;"></span><span class="mord mathnormal" style="margin-right:0.1132em;">τ</span></span></span></span> 与 Spearman 的 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.625em;vertical-align:-0.1944em;"></span><span class="mord mathnormal">ρ</span></span></span></span>，都是把自动打分给出的模型排名与专家标注给出的排名做比较。选秩相关而非绝对误差是合理的，因为不同打分体系的绝对尺度本就不可比，实践中人们真正关心的也是排序。</p><h2 id="§-7-—-实验设计与结论" tabindex="-1">§ 7 — 实验设计与结论 <a class="header-anchor" href="#§-7-—-实验设计与结论" aria-label="Permalink to &quot;§ 7 — 实验设计与结论&quot;">​</a></h2><p>第一个问题：当前最强的模型在复合科学推理上到底行不行。作者评了七个系统——Sora-2、Veo-3、Seedance 1.0 Pro、Kling-v2.5-Turbo-Pro、Hailuo 2.3、Ray2、Wan-2.5-T2V-Preview，每题每模型生成三条（Veo-3 因 API 成本过高只生成一条），由领域专家按五维打分。结果分层非常清楚：时空连贯性与不变性这两个传统 benchmark 强调的维度，多数模型表现良好；而 Phenomenon Congruency 上，即使最强的闭源系统 Sora-2 与 Veo-3 也只有约 64% 与 58.7%，最强开源的 Wan-2.5 约 46%。Prompt Consistency 同样不乐观——Sora-2 与 Veo-3 平均分虽超过 3，但在多物体交互的复杂装置上经常搭不对。</p><p>第二个问题：自动判分能不能替代专家。VideoScience-Judge 与人类标注的秩相关达到 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.4306em;"></span><span class="mord mathnormal" style="margin-right:0.1132em;">τ</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">0.81</span></span></span></span>、<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.625em;vertical-align:-0.1944em;"></span><span class="mord mathnormal">ρ</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">0.89</span></span></span></span>，加了清单的变体升到 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.4306em;"></span><span class="mord mathnormal" style="margin-right:0.1132em;">τ</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">0.90</span></span></span></span>、<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.625em;vertical-align:-0.1944em;"></span><span class="mord mathnormal">ρ</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">0.96</span></span></span></span>；作为对照，PhyGenEval 的 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.625em;vertical-align:-0.1944em;"></span><span class="mord mathnormal">ρ</span></span></span></span> 只有 0.61，VideoScore2 是 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.4306em;"></span><span class="mord mathnormal" style="margin-right:0.1132em;">τ</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">0.24</span></span></span></span>、<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.625em;vertical-align:-0.1944em;"></span><span class="mord mathnormal">ρ</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">0.29</span></span></span></span>，T2V-CompBench 的属性绑定指标用 Llava-1.5-7B 判分是 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.4306em;"></span><span class="mord mathnormal" style="margin-right:0.1132em;">τ</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">0.62</span></span></span></span>、<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.625em;vertical-align:-0.1944em;"></span><span class="mord mathnormal">ρ</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">0.75</span></span></span></span>。论文对 PhyGenEval 的失效给出了机制解释：强制二值判断造成分数量化，规则式提问抓不到轨迹一致性、跨时间因果、加速度模式这类整体性判断，而 VideoScience-Bench 的题目恰恰是多个定律叠加、二阶动态才决定结果。</p><p>第三个问题：判分器的设计选择各贡献多少。用非推理模型 GPT-4o 作 backbone 时打分严重正偏，即使做了 min-max 归一化，Coherence 与 Immutability 上的绝对偏差仍高达 0.384 与 0.417；换成 GPT-5 pro 后偏差最多降低 57%，但 Dynamism、Coherence、Immutability 上仍有系统性高估。加入清单并要求用关键帧证据逐条论证后高估明显收窄，再接入 CV 工具（尤其是 ByteTrack 提供的跨帧身份关联，可以为帧跳变和物体突变提供硬证据）进一步把 Coherence 与 Immutability 的差距各压掉 0.07 与 0.09。</p><p>定性上最有信息量的是两个失败案例：铝碘反应里 Sora-2 完整画出了点燃现象而 Hailuo-2.3 生成了一个什么都没发生的静态视频；而&quot;两只杯口对口用木棍连接、内各放一球、绕中心快速旋转&quot;这道离心力题，排名前二的 Sora-2 与 Veo-3 双双失败——前者装置部分对但现象错，后者连装置都没搭对。这说明文本模型能轻松推出的结论，视频模型仍然画不出来。</p><h2 id="§-8-—-take-aways" tabindex="-1">§ 8 — Take-aways <a class="header-anchor" href="#§-8-—-take-aways" aria-label="Permalink to &quot;§ 8 — Take-aways&quot;">​</a></h2><p><strong>五句话版</strong>：论文把视频评测从物理常识推进到本科级科学推理，每条 prompt 至少复合两个概念，共 200 条覆盖 14 个主题与 103 个概念。专家标注显示当前模型在时空连贯性与不变性上已接近饱和，但在&quot;是否产生了正确现象&quot;上最强系统也只有约六成。判分侧提出 VideoScience-Judge，用题目专属清单加关键帧证据加确定性 CV 证据表约束 VLM 打分。它与专家排名的相关性显著高于 PhyGenEval、VideoScore2 与 T2V-CompBench。非推理 VLM 作判分器会系统性虚高，推理型模型加清单加 CV 证据是把这个偏差压下来的关键。</p><p><strong>三句话版</strong>：把 prompt 从&quot;描述现象&quot;改成&quot;描述装置&quot;，视频模型的分数立刻塌陷，说明此前的高分主要来自记忆而非推理。让 VLM 判分变得可靠的办法是剥夺它的自由度：先给清单，再要求每次扣分都指出帧和证据。当前 SOTA 在这套题上离及格还有明显距离，且开源与闭源差距在现象正确性这一维上最大。</p><p><strong>一句话版</strong>：只有当题目需要两个定律同时起作用时，才分得清视频模型是在推理还是在检索。</p><h2 id="§-9-—-最脆弱的假设" tabindex="-1">§ 9 — 最脆弱的假设 <a class="header-anchor" href="#§-9-—-最脆弱的假设" aria-label="Permalink to &quot;§ 9 — 最脆弱的假设&quot;">​</a></h2><p>最脆弱的假设是：<strong>标准答案（expected phenomenon）本身是唯一且确定的</strong>，因而&quot;生成结果与标准答案不符&quot;可以直接判为模型的科学理解错误。复合科学场景恰恰不满足这一点——真实实验的结果强烈依赖那些自然语言 prompt 无法完全指定的参数。水气球靠近烛焰能撑多久，取决于水量、火焰距离、橡胶厚度；热水冷水对口分层是否稳定，取决于温差、杯口密封、移除隔板的速度。一段 10 秒的视频完全可能落在一个物理上合法但与作者预设不同的参数区间里，却被判为 Phenomenon Congruency 只有 1 或 2 分。这一点直接威胁核心结论，因为整个&quot;模型缺乏科学推理&quot;的判断压在这一维上，而它的权重又是最高的 0.3。论文提供的缓解证据是：题目取自公开教学实验资料、经过全体评审交叉核对、并用 Sora-2 与 Wan-2.5 预生成确认可实现性。缺的证据是对<strong>标注者间一致性</strong>的报告——如果两位专家对同一段生成视频的 Phenomenon Congruency 分歧本身就有一分左右，那么模型间几个百分点的差距就不具备分辨力。文中未见 inter-annotator agreement 数据。</p><h2 id="§-10-—-最小复现实验" tabindex="-1">§ 10 — 最小复现实验 <a class="header-anchor" href="#§-10-—-最小复现实验" aria-label="Permalink to &quot;§ 10 — 最小复现实验&quot;">​</a></h2><p>不需要复现全部 200 条题目，一周内可完成一个针对上述脆弱点的检验。第一步，从 T2V 分支挑 20 条题目，其中 10 条的预期现象对未指定参数敏感（涉及温度、浓度、质量比、时长），另 10 条不敏感（如颜色变化、是否燃烧这类二值结果）。第二步，对每条题目请三位未参与出题的理工科研究生独立按五维打分，对象是同一批已有的生成视频。第三步，分别计算两组题目上的标注者间一致性（如 Krippendorff 的 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.4306em;"></span><span class="mord mathnormal" style="margin-right:0.0037em;">α</span></span></span></span>）以及各自的模型排名。判据：若参数敏感组的一致性显著低于不敏感组（例如 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.4306em;"></span><span class="mord mathnormal" style="margin-right:0.0037em;">α</span></span></span></span> 相差 0.2 以上），且两组给出的模型排名不一致，则说明榜单的一部分信号来自出题者的参数预设而非模型能力，benchmark 需要为这类题目补充可接受结果的区间说明；若两组一致性接近，则该脆弱点被排除，结论稳固。</p><h2 id="§-11-—-最强反例设计" tabindex="-1">§ 11 — 最强反例设计 <a class="header-anchor" href="#§-11-—-最强反例设计" aria-label="Permalink to &quot;§ 11 — 最强反例设计&quot;">​</a></h2><p>站在反对者立场，最有力的攻击是提出一个替代解释：模型在 Phenomenon Congruency 上得分低，主要不是因为不理解科学，而是因为 <strong>prompt 描述的装置本身超出了它的可控生成能力</strong>。论文自己的数据支持这条路径——Prompt Consistency 在复杂多物体交互场景下明显下降，而装置搭错的视频不可能产生正确现象。也就是说，两个维度之间存在混淆：一个只会画简单场景的模型会在两项上同时失分，看起来像&quot;不懂科学&quot;，实际上只是&quot;画不出实验台&quot;。旋转杯球那道题正是佐证：Veo-3 装置就没搭对，它的现象错误无法归因于对离心力的误解。</p><p>设计的检验实验是条件化剥离：把 40 条 I2V 题目扩充到全部 160 条，即为每道题都提供一张<strong>正确装置的首帧图像</strong>，从而把&quot;能否搭对装置&quot;这一环节完全移除。然后比较同一模型在 T2V 与 I2V 两种条件下的 Phenomenon Congruency。若给定正确起始状态后现象正确率大幅回升（比如 Sora-2 从 64% 升到 85% 以上），那么论文关于&quot;模型缺乏科学推理&quot;的结论就被大幅削弱，真正的瓶颈是可控生成；若正确率几乎不变，则科学推理缺口是独立且真实的，结论反而被显著加强。这个实验的成本主要是生成与标注，作者已经具备全部基础设施。</p><h2 id="§-12-—-follow-up-research-idea" tabindex="-1">§ 12 — Follow-up Research Idea <a class="header-anchor" href="#§-12-—-follow-up-research-idea" aria-label="Permalink to &quot;§ 12 — Follow-up Research Idea&quot;">​</a></h2><p>论文把视频模型当成一个只能被观测输出的黑箱来考试，答案是&quot;考不及格&quot;。但一个更有价值的 framing 是：把生成过程本身当作<strong>可干预的推理链</strong>，而不是一次性采样。真实科学推理的特征是分阶段的——先确定初始状态，再推演中间态，最后得到终态；而当前的视频扩散把这三步压进一次去噪，任何一步的错误都无法定位，更无法纠正。可借鉴的相邻领域工具是语言模型上已经成熟的过程监督（process supervision）与自洽性采样：那里的关键发现是，对中间步骤打分比对最终答案打分能提供强得多的训练与选择信号。搬到视频上，对应的做法是把一道题拆成若干个带时间戳的中间现象断言（&quot;第 2 秒水已经浸没铝粉&quot;&quot;第 4 秒出现紫色烟&quot;），让模型分段生成、每段接受一次断言级判分，并允许在断言失败时回滚重采样该段。</p><p>第一个实验不需要训练任何模型：在现有的 200 条题目上，为每条标注 2–4 个中间断言，然后对同一模型做 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6944em;"></span><span class="mord mathnormal" style="margin-right:0.0315em;">k</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">8</span></span></span></span> 次采样，用 VideoScience-Judge 的清单机制逐段核验断言，比较&quot;整段采样取最好&quot;与&quot;分段采样、每段按断言择优拼接&quot;两种策略下的最终 Phenomenon Congruency。如果分段择优带来的提升远大于整段 best-of-<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6944em;"></span><span class="mord mathnormal" style="margin-right:0.0315em;">k</span></span></span></span>，就说明模型内部其实具备正确推演每一步的能力，只是无法在一次长采样中把它们串对——那么问题的性质从&quot;缺乏科学知识&quot;变成&quot;缺乏推理过程的可控性&quot;，后续该做的是过程级的对齐而不是更大的模型。</p>',39)])])}const u=a(p,[["render",l]]);export{g as __pageData,u as default};
